import{_ as i,C as r,o as n,c as h,j as e,a as d,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const P=JSON.parse('{"title":"警告提示","description":"","frontmatter":{},"headers":[],"relativePath":"components/alert.md","filePath":"components/alert.md","lastUpdated":1787173379000}'),s={name:"components/alert.md"},p={id:"警告提示",tabindex:"-1"};function b(u,t,x,g,f,m){const l=r("Badge"),a=r("XhDemo");return n(),h("div",null,[e("h1",p,[t[0]||(t[0]=d("警告提示 ",-1)),o(l,{type:"info",text:"alert"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#警告提示","aria-label":'Permalink to "警告提示 <Badge type="info" text="alert" />"'},"​",-1))]),t[3]||(t[3]=c('<p>页面里常驻的一条提示：说明一件与当前上下文有关的事。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>表单顶部的整体错误、页面级的状态说明、功能公告。</li><li>信息需要一直在，直到用户处理或关闭。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是一次操作的结果反馈：用<a href="./toast">轻提示</a>——它会自己消失。</li><li>需要用户当场做决定并阻断流程：用<a href="./dialog">对话框</a>。</li><li>是一个字段的错误：用<a href="./field">表单字段</a>的错误文本。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>语气决定用哪族颜色，图标由作者放。</li><li><code>closable</code> 给出关闭按钮，关闭态可受控。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>各部件按需摆放，标题与描述都是可选的</p>',10)),o(a,{src:"alert/01-basic"}),t[4]||(t[4]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[5]||(t[5]=e("p",null,"tone 只改配色，语义仍由内容与 role 决定",-1)),o(a,{src:"alert/02-tone"}),t[6]||(t[6]=e("h3",{id:"可关闭",tabindex:"-1"},[d("可关闭 "),e("a",{class:"header-anchor",href:"#可关闭","aria-label":'Permalink to "可关闭"'},"​")],-1)),t[7]||(t[7]=e("p",null,"closable 开启后才渲染关闭按钮；open 受控时由宿主决定去留",-1)),o(a,{src:"alert/03-closable"}),t[8]||(t[8]=e("h3",{id:"图标",tabindex:"-1"},[d("图标 "),e("a",{class:"header-anchor",href:"#图标","aria-label":'Permalink to "图标"'},"​")],-1)),t[9]||(t[9]=e("p",null,"icon 部件排在标题前面，颜色取当前语气的强调色；内容由作者塞，字形与内联 svg 都行",-1)),o(a,{src:"alert/04-icon"}),t[10]||(t[10]=e("h3",{id:"自定义外观",tabindex:"-1"},[d("自定义外观 "),e("a",{class:"header-anchor",href:"#自定义外观","aria-label":'Permalink to "自定义外观"'},"​")],-1)),t[11]||(t[11]=e("p",null,"描边、底色、标题色、圆角各是一个组件令牌；描边槽位换成透明就只剩淡底，尺寸不变",-1)),o(a,{src:"alert/05-custom"}),t[12]||(t[12]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-alert&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhAlertCloseTrigger</code> <code>XhAlertDescription</code> <code>XhAlertIcon</code> <code>XhAlertRoot</code> <code>XhAlertTitle</code></td></tr><tr><td>状态机</td><td><code>alertMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/alert.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;alert&quot;</code>：<strong><code>root</code></strong> · <code>icon</code> · <code>title</code> · <code>description</code> · <code>close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色，默认 info。 danger / warning 走 role=&quot;alert&quot;，其余走 role=&quot;status&quot;。</td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td><td>关闭按钮是否可用，默认 true。false 时该按钮同时被禁用与收起。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td>受控显隐；缺省该 prop 即非受控。</td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td>非受控初始显隐，默认显示。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: AlertOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;AlertTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>AlertOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>tone</code></td><td><code>string</code></td><td></td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIconProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/alert/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus 在 close-trigger 上且 closable</td><td>收起提示并通知 open=false</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-live</code></td><td>live</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>role</td></tr><tr><td><code>icon</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/alert.css</code> 按部件选择：<code>[data-scope=&quot;alert&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>close-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-alert-bg</code> · <code>--xh-alert-border</code> · <code>--xh-alert-close-fg</code> · <code>--xh-alert-close-fg-hover</code> · <code>--xh-alert-close-radius</code> · <code>--xh-alert-close-size</code> · <code>--xh-alert-description-fg</code> · <code>--xh-alert-description-font-size</code> · <code>--xh-alert-fg</code> · <code>--xh-alert-font-size</code> · <code>--xh-alert-gap</code> · <code>--xh-alert-icon-fg</code> · <code>--xh-alert-icon-size</code> · <code>--xh-alert-leading</code> · <code>--xh-alert-px</code> · <code>--xh-alert-py</code> · <code>--xh-alert-radius</code> · <code>--xh-alert-title-fg</code> · <code>--xh-alert-title-font-size</code> · <code>--xh-alert-title-font-weight</code> · <code>--xh-alert-title-leading</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>图标用<a href="./icon">图标</a>；里面的行动入口用<a href="./button">按钮</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>说清楚发生了什么、影响是什么、用户能做什么，三样缺一不可。</li><li>语气别只靠颜色，标题文字本身就要说明严重程度。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>一屏堆好几条提示：用户会全部略过。</li><li>用它做营销位。</li></ul>',42))])}const k=i(s,[["render",b]]);export{P as __pageData,k as default};
